import {playerNitro} from './racing-nitro.mjs?v=20261026-nitro';
export function boostVisual(race){return playerNitro(race)&&race.phase==='running'?Math.max(0,Math.min(1,(race.speed*3.6-220)/80)):0;}
// Bounded, deterministic streaks: no DOM animation, timers, filters or frame history.
export function drawSpeedEffects(ctx,race,width,height,view,{overview=false,reduced=false}={}){const strength=boostVisual(race);if(!strength)return 0;ctx.save();const cockpit=view==='cockpit',bottom=cockpit?height*.44:height*.88,centerX=width*.5,centerY=height*(cockpit?.24:.43),count=reduced?8:28;ctx.beginPath();ctx.rect(0,56,width,Math.max(0,bottom-56));ctx.clip();for(let i=0;i<count;i++){const phase=(race.distance*.025+i*.61803398875)%1,side=i%2?-1:1,edge=centerX+side*width*(.33+.3*phase),y=60+((i*.173+phase)%1)*Math.max(1,bottom-60),dx=edge-centerX,dy=y-centerY,length=(reduced?.035:.09+.14*phase)*strength;ctx.strokeStyle=`rgba(195,232,245,${(.16+.4*phase)*strength})`;ctx.lineWidth=.7+phase*1.3;ctx.beginPath();ctx.moveTo(edge-dx*length,y-dy*length);ctx.lineTo(edge,y);ctx.stroke();}ctx.restore();return count;}
export function drawExhaust2D(ctx,race,x,y,size,{aerial=false,heading=0}={}){if(!playerNitro(race)||race.phase!=='running')return;ctx.save();ctx.translate(x,y);if(aerial)ctx.rotate(heading);const pulse=.85+.15*Math.sin(race.elapsed*73);for(const side of [-1,1]){const w=Math.max(3,size*.085),length=size*(aerial?.42:.27)*pulse,cx=side*size*.31;const g=ctx.createLinearGradient(cx,0,cx,length);g.addColorStop(0,'#e9fbff');g.addColorStop(.2,'#79caff');g.addColorStop(.52,'#ffbd50');g.addColorStop(1,'#ff4b0800');ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(cx-w,0);ctx.quadraticCurveTo(cx-w*.7,length*.7,cx,length);ctx.quadraticCurveTo(cx+w*.7,length*.7,cx+w,0);ctx.fill();}ctx.restore();}
